int main()
{
    int n, i, a[100], *left, *right, t;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    left = a;
    right = a + n - 1;
    while (left < right)
    {
        t = *left;
        *left = *right;
        *right = t;
        left++;
        right--;
    }
    for (i = 0; i < n; i++)
    {
        printf("%d", a[i]);
        if (i < n - 1)
            printf(" ");
    }
    printf("\n");
    return 0;
}

