#include <stdio.h>

void reverse(char *s)
{
    char *p = s, *q = s, t;
    while (*q != '\0')
        q++;
    q--;
    while (p < q)
    {
        t = *p;
        *p = *q;
        *q = t;
        p++;
        q--;
    }
}

int main()
{
    char s[60];
    scanf("%s", s);
    reverse(s);
    printf("%s\n", s);
    return 0;
}

