int main()
{
    int n, i, t, a[100];
    int *p, *q, *minp;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    for (p = a; p < a + n - 1; p++)
    {
        minp = p;
        for (q = p + 1; q < a + n; q++)
            if (*q < *minp)
                minp = q;
        if (minp != p)
        {
            t = *p;
            *p = *minp;
            *minp = t;
        }
    }
    for (p = a; p < a + n; p++)
    {
        if (p != a)
            printf(" ");
        printf("%d", *p);
    }
    printf("\n");
    return 0;
}

