#include <stdio.h>

void mm(int *a, int n, int *pmax, int *pmin)
{
    int i;
    *pmax = a[0];
    *pmin = a[0];
    for (i = 1; i < n; i++)
    {
        if (a[i] > *pmax)
            *pmax = a[i];
        if (a[i] < *pmin)
            *pmin = a[i];
    }
}

int main()
{
    int n, i, a[100], mx, mn;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    mm(a, n, &mx, &mn);
    printf("%d %d\n", mx, mn);
    return 0;
}
